import "@stdlib/gas-payments"
import "bitmap"
import "errors"
import "messages"
import "storage"
import "validate-c5"

contract HighloadWalletV3 {
    author: "The Tolk Team"
    version: "1.0.0"
    description: "Highload Wallet V3. Batch transaction wallet for high-volume operations"
    incomingMessages: InternalTransfer
    storage: HighloadWalletStorage
}

fun onInternalMessage(in: InMessage) {
    val (bodyBits, bodyRefs) = in.body.remainingBitsAndRefsCount();
    if (bodyRefs != 1 || bodyBits != INTERNAL_TRANSFER_BODY_BITS) {
        return; // just accept tons
    }

    if (in.senderAddress != contract.getAddress()) {
        return; // just accept tons
    }

    if (in.body.preloadUint(32) != OP_INTERNAL_TRANSFER) {
        return;
    }

    val msg = lazy InternalTransfer.fromSlice(in.body);

    setTvmRegisterC5(msg.actions);
    val oldCode = contract.getCode();
    contract.setCodePostponed(oldCode); // prevent actions from changing code
}

fun onExternalMessage(inBody: slice) {
    val msg = lazy ExternalTransferRequest.fromSlice(inBody);

    val msgInner = msg.inner;
    val signature = msg.signature;

    val now = blockchain.now();
    var storage = lazy HighloadWalletStorage.load();
    storage.cleanupQueryWindows(now);

    assert (
        isSignatureValid(msgInner.hash(), signature as slice, storage.publicKey)
    ) throw ERROR_INVALID_SIGNATURE;

    val request = msgInner.load();

    val createdAt = request.createdAt;
    val timeout = storage.timeout;
    val shift = request.shift;
    val bitNumber = request.bitNumber;

    assert (request.subwalletId == storage.subwalletId) throw ERROR_INVALID_SUBWALLET_ID;
    assert (request.timeout == timeout) throw ERROR_INVALID_TIMEOUT;
    assert (createdAt > (now - timeout)) throw ERROR_INVALID_CREATED_AT;
    assert (createdAt <= now) throw ERROR_INVALID_CREATED_AT;

    assert (
        !storage.oldQueries.isProcessedInQueryMap(shift, bitNumber)
    ) throw ERROR_ALREADY_EXECUTED;

    val updatedBitmap = storage.queries.markProcessed(shift, bitNumber);

    acceptExternalMessage();

    storage.queries.set(shift, updatedBitmap);

    storage.save();
    commitContractDataAndActions();

    if (!validateMessageToSend(request.messageToSend)) {
        return;
    }

    sendRawMessage(request.messageToSend, request.sendMode | SEND_MODE_IGNORE_ERRORS);
}

get fun get_public_key(): int {
    val storage = lazy HighloadWalletStorage.load();
    return storage.publicKey;
}

get fun get_subwallet_id(): int {
    val storage = lazy HighloadWalletStorage.load();
    return storage.subwalletId;
}

get fun get_last_clean_time(): int {
    val storage = lazy HighloadWalletStorage.load();
    return storage.lastCleanTime;
}

get fun get_timeout(): int {
    val storage = lazy HighloadWalletStorage.load();
    return storage.timeout;
}

fun queryIdShift(queryId: int): uint13 {
    return (queryId >> BIT_NUMBER_SIZE);
}

fun queryIdBitNumber(queryId: int): int {
    return queryId & CELL_BITS_SIZE;
}

get fun `processed?`(queryId: int, needClean: int): bool {
    val shift = queryIdShift(queryId);
    val bitNumber = queryIdBitNumber(queryId);

    var storage = lazy HighloadWalletStorage.load();
    if (needClean != 0) {
        storage.cleanupQueryWindows(blockchain.now());
    }

    if (storage.oldQueries.isProcessedInQueryMap(shift, bitNumber)) {
        return true;
    }
    if (storage.queries.isProcessedInQueryMap(shift, bitNumber)) {
        return true;
    }

    return false;
}

import "errors"

const CELL_BITS_SIZE = 1023
const BIT_NUMBER_SIZE = 10

// SAFETY: single safe builder mutation
fun builder.storeZeroes(mutate self, len: int): self
    asm "STZEROES"

type Bitmap = cell

fun Bitmap.build(bitNumber: int): Bitmap {
    var b = beginCell();
    b.storeZeroes(bitNumber);
    b.storeBool(true);
    b.storeZeroes(CELL_BITS_SIZE - bitNumber - 1);
    return b.endCell();
}

type QueryBitmapMap = map<uint13, Bitmap>

fun QueryBitmapMap.isProcessedInQueryMap(self, shift: uint13, bitNumber: int): bool {
    val lookup = self.get(shift);

    var res: bool;

    if (!lookup.isFound) {
        res = false;
    } else {
        var valueSlice = lookup.loadValue().beginParse();
        valueSlice.skipBits(bitNumber);

        res = valueSlice.preloadInt(1) != 0;
    }

    return res;
}

fun QueryBitmapMap.markProcessed(self, shift: uint13, bitNumber: int): Bitmap {
    val nextQueries = self;
    val lookup = nextQueries.get(shift);

    var res: Bitmap;

    if (lookup.isFound) {
        var tail = lookup.loadValue().beginParse();
        val head = tail.loadBits(bitNumber);
        assert (!tail.loadBool()) throw ERROR_ALREADY_EXECUTED;
        res = beginCell().storeSlice(head).storeBool(true).storeSlice(tail).endCell();
    } else {
        res = Bitmap.build(bitNumber);
    }

    return res;
}

const OP_INTERNAL_TRANSFER = 0xae42e5a4

struct (0xae42e5a4) InternalTransfer {
    queryId: uint64
    actions: cell // c5
}

struct MsgInner {
    subwalletId: uint32
    messageToSend: cell
    sendMode: uint8
    shift: uint13
    bitNumber: uint10
    createdAt: uint64
    timeout: uint22
}

struct ExternalTransferRequest {
    signature: bits512
    inner: Cell<MsgInner>
}

import "bitmap"

const INTERNAL_TRANSFER_BODY_BITS = 32 + 64

struct HighloadWalletStorage {
    publicKey: uint256
    subwalletId: uint32
    oldQueries: QueryBitmapMap
    queries: QueryBitmapMap
    lastCleanTime: uint64
    timeout: uint22
}

fun HighloadWalletStorage.load(): HighloadWalletStorage {
    return HighloadWalletStorage.fromCell(contract.getData());
}

fun HighloadWalletStorage.save(self) {
    contract.setData(self.toCell());
}

fun HighloadWalletStorage.cleanupQueryWindows(mutate self, now: int) {
    val timeout = self.timeout;
    val lastCleanTime = self.lastCleanTime;

    if (lastCleanTime < (now - timeout)) {
        self.oldQueries = self.queries;
        self.queries = [];

        if (lastCleanTime < (now - (timeout * 2))) {
            self.oldQueries = [];
        }

        self.lastCleanTime = now;
    }
}

import "errors"

// SAFETY: we validate raw actions before setting them
fun setTvmRegisterC5(actions: cell): void
    asm "c5 POP"

struct CurrencyCollection {
    grams: coins
    other: map<int32, varuint32>
}

struct (0b0) IntMsgInfoRelaxed {
    ihrDisabled: bool
    bounce: bool
    bounced: bool
    src: any_address
    dest: address
    value: CurrencyCollection
    extraFlags: varuint16
    fwdFee: coins
    createdLt: uint64
    createdAt: uint32
}

type EitherBody = RemainingBitsAndRefs

// "body" is TL/B `(Either Cell ^Cell)`;
// we want to test, that if ^Cell, no other data exists in a slice
fun EitherBody.checkIsCorrectTlbEither(self) {
    var mutableCopy = self;
    if (mutableCopy.loadMaybeRef() != null) {
        // throw "cell underflow" if there is data besides a ref
        mutableCopy.assertEnd();
    }
}

struct MessageRelaxed {
    info: IntMsgInfoRelaxed
    maybeStateInit: bool
    body: EitherBody
}

fun validateMessageToSend(messageToSend: cell): bool {
    val msg = lazy MessageRelaxed.fromCell(
        messageToSend,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_MESSAGE_TO_SEND },
    );

    var res: bool;

    if (msg.info.bounced) {
        res = false;
    } else {
        assert (msg.info.src.isNone()) throw ERROR_INVALID_MESSAGE_TO_SEND;
        assert (!msg.maybeStateInit) throw ERROR_INVALID_MESSAGE_TO_SEND;
        msg.body.checkIsCorrectTlbEither();

        res = true;
    }

    return res;
}
